  function lang(){var value=String(root.LOCALE||document.documentElement.lang||'fr').toLowerCase().slice(0,2);return COPY[value]?value:'fr';}
  function t(key){return (COPY[lang()]||COPY.fr)[key]||COPY.fr[key]||key;}
  function escapeHTML(value){return String(value==null?'':value).replace(/[&<>"']/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch];});}
  function activeId(){try{return String(root.STORE&&root.STORE.actif||'etab_1').slice(0,120);}catch(error){return 'etab_1';}}
  function activeName(){try{return String(root.verdictEtabIdentity(root.DB).name||'Mon établissement');}catch(error){return 'Mon établissement';}}
  function timezone(){try{return String(root.DB.businessTimezone||root.DB.orderingSettings&&root.DB.orderingSettings.timezone||'Europe/Paris');}catch(error){return 'Europe/Paris';}}
  function authenticated(){return !!(root.VERDICT_ACCOUNT_STATE&&root.VERDICT_ACCOUNT_STATE.auth===true&&location.protocol.indexOf('http')===0);}
  function csrf(){return root.VERDICT_ACCOUNT_STATE&&root.VERDICT_ACCOUNT_STATE.csrf||'';}
  function api(action,payload,write){if(!authenticated())return Promise.reject(new Error('authentication_required'));var headers={'Content-Type':'application/json'};if(write)headers['X-CSRF-Token']=csrf();return fetch(ENDPOINT,{method:'POST',credentials:'same-origin',headers:headers,body:JSON.stringify(Object.assign({action:action,etabId:activeId()},payload||{}))}).then(function(response){return response.json().catch(function(){return {};}).then(function(json){if(!response.ok)throw Object.assign(new Error(json.error||'flux_unavailable'),{status:response.status});return json;});});}
  function ensure(){return api('ensure_establishment',{name:activeName(),timezone:timezone()},true);}
  function operational(){try{return root.verdictOperationalClock();}catch(error){var now=new Date();return {key:now.toISOString().slice(0,10),day:now.getDate()};}}
