  function close(){var node=modal();node.hidden=true;node.innerHTML='';}
  function shell(body){var node=modal();node.innerHTML='<section class="v451-flux-sheet" role="dialog" aria-modal="true" style="position:relative"><div class="v451-flux-grab"></div><button type="button" class="v451-flux-x" data-flux-close aria-label="'+escapeHTML(t('close'))+'" style="position:absolute;top:12px;right:12px;width:40px;height:40px;display:grid;place-items:center;border-radius:50%;border:1px solid rgba(148,163,184,.35);background:transparent;color:inherit;font:inherit;font-size:22px;line-height:1;cursor:pointer;z-index:2">×</button>'+body+'</section>';/* C388 (audit A40) : la croix suit chaque réécriture de la feuille */node.hidden=false;var focus=node.querySelector('input,button,a');if(focus)root.setTimeout(function(){try{focus.focus({preventScroll:true});}catch(error){}},30);return node;}
  function connection(){return state.connections.filter(function(item){return item.state==='active'||item.state==='error';})[0]||null;}
